/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202a30;
  --ink-deep: #172127;
  --slate: #526168;
  --muted: #77838a;
  --paper: #f7f6f2;
  --white: #ffffff;
  --sand: #e9e5dc;
  --orange: #c56b3d;
  --orange-dark: #a9512c;
  --line: #deded8;
  --font-display: "DM Serif Display", Georgia, serif;
  --font-body: "DM Sans", Arial, sans-serif;
  --container: 1200px;
  --radius: 5px;
  --shadow: 0 16px 45px rgba(23, 33, 39, 0.10);
}

/* RESET */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

::selection {
  color: var(--white);
  background: var(--orange);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--ink-deep);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
}

h1 {
  font-size: clamp(3rem, 6.5vw, 5.6rem);
  letter-spacing: -0.045em;
}

h2 {
  font-size: clamp(2.25rem, 4vw, 3.65rem);
  letter-spacing: -0.035em;
}

h3 {
  font-size: 1.65rem;
}

p {
  margin: 0 0 1.25rem;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--orange-dark);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 2px;
  background: currentColor;
  content: "";
}

.section-intro {
  max-width: 650px;
  margin-bottom: 52px;
}

.section-intro p {
  margin-top: 20px;
  color: var(--slate);
  font-size: 1.05rem;
}

/* PAGE STRUCTURE */
.container {
  width: min(var(--container), calc(100% - 64px));
  margin-inline: auto;
}

.section {
  padding: 112px 0;
}

.section--white {
  background: var(--white);
}

.section--dark {
  background: var(--ink-deep);
  color: var(--white);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark p {
  color: #c5ccce;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 42, 48, 0.08);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  flex-shrink: 0;
}

.brand-mark {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  background: var(--ink);
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.55rem;
  border-bottom: 3px solid var(--orange);
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.brand-name {
  color: var(--ink-deep);
  font-size: 0.94rem;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.brand-description {
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 30px;
}

.main-nav a {
  color: var(--slate);
  font-size: 0.82rem;
  font-weight: 700;
  transition: color 180ms ease;
}

.main-nav a:hover {
  color: var(--orange-dark);
}

.header-contact {
  display: flex;
  align-items: center;
  gap: 18px;
}

.header-phone {
  color: var(--ink);
  font-size: 0.88rem;
  font-weight: 800;
  white-space: nowrap;
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--orange);
  color: var(--white);
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.035em;
  text-align: center;
  transition:
    background 180ms ease,
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--orange-dark);
}

.button--dark {
  background: var(--ink);
}

.button--dark:hover {
  background: var(--ink-deep);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--ink);
}

.button--light {
  background: var(--white);
  color: var(--ink);
}

.button--light:hover {
  background: var(--sand);
}

/* HERO */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--ink-deep);
  color: var(--white);
}

.hero-inner {
  display: grid;
  min-height: 650px;
  grid-template-columns: 1.02fr 0.98fr;
  align-items: center;
}

.hero-copy {
  position: relative;
  z-index: 2;
  padding: 88px 50px 88px 0;
}

.hero .eyebrow {
  color: #e5a27d;
}

.hero h1 {
  max-width: 690px;
  color: var(--white);
}

.hero h1 em {
  color: #e6a47e;
  font-style: normal;
}

.hero-description {
  max-width: 510px;
  margin: 25px 0 32px;
  color: #c5ccce;
  font-size: 1.08rem;
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-proof {
  display: flex;
  flex-wrap: wrap;
  gap: 25px;
  margin-top: 45px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.17);
}

.hero-proof-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.hero-proof-item strong {
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.65rem;
  font-weight: 400;
}

.hero-proof-item span {
  color: #b6c0c3;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.hero-visual {
  position: relative;
  height: 100%;
  min-height: 650px;
}

.hero-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.hero-visual::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(23, 33, 39, 0.28),
    rgba(23, 33, 39, 0.02) 60%
  );
  content: "";
}

.hero-caption {
  position: absolute;
  z-index: 2;
  right: 25px;
  bottom: 25px;
  left: 25px;
  padding: 19px 22px;
  background: rgba(23, 33, 39, 0.88);
  border-left: 3px solid var(--orange);
  color: var(--white);
  font-size: 0.82rem;
  font-weight: 700;
}

/* POSITIONING / WHY CHOOSE US */
.approach-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: start;
  gap: 90px;
}

.approach-heading {
  position: sticky;
  top: 40px;
}

.approach-heading h2 {
  max-width: 460px;
}

.approach-heading p {
  max-width: 430px;
  margin-top: 24px;
  color: var(--slate);
}

.approach-content {
  padding-top: 8px;
}

.approach-item {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 22px;
  padding: 27px 0;
  border-bottom: 1px solid var(--line);
}

.approach-item:first-child {
  padding-top: 0;
}

.approach-number {
  color: var(--orange);
  font-family: var(--font-display);
  font-size: 1.6rem;
}

.approach-item h3 {
  margin-bottom: 10px;
}

.approach-item p {
  margin: 0;
  color: var(--slate);
  font-size: 0.95rem;
}

/* ROOFING / HAIL RESTORATION */
.roof-layout {
  display: grid;
  grid-template-columns: 1fr 0.9fr;
  align-items: center;
  gap: 75px;
}

.roof-content h2 {
  max-width: 570px;
}

.roof-content > p {
  max-width: 540px;
  margin-top: 22px;
  color: var(--slate);
}

.roof-checklist {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px 25px;
  margin: 32px 0;
  padding: 0;
  list-style: none;
}

.roof-checklist li {
  position: relative;
  padding-left: 25px;
  color: var(--ink);
  font-size: 0.91rem;
  font-weight: 700;
}

.roof-checklist li::before {
  position: absolute;
  top: 0;
  left: 0;
  color: var(--orange);
  font-weight: 900;
  content: "✓";
}

.roof-image-wrap {
  position: relative;
  min-height: 480px;
}

.roof-image {
  width: 100%;
  height: 480px;
  object-fit: cover;
  object-position: center;
}

.roof-image-label {
  position: absolute;
  right: -18px;
  bottom: 25px;
  max-width: 240px;
  padding: 18px 22px;
  background: var(--ink);
  color: var(--white);
  font-size: 0.82rem;
  font-weight: 700;
}

/* COLORADO ROOFING GUIDE */
.guide-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 85px;
}

.guide-heading {
  max-width: 410px;
}

.guide-heading p {
  margin-top: 20px;
  color: var(--slate);
}

.guide-steps {
  border-top: 1px solid var(--line);
}

.guide-step {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 20px;
  padding: 24px 0;
  border-bottom: 1px solid var(--line);
}

.guide-step-number {
  color: var(--orange);
  font-family: var(--font-display);
  font-size: 2rem;
  line-height: 1;
}

.guide-step h3 {
  margin-bottom: 8px;
}

.guide-step p {
  margin: 0;
  color: var(--slate);
  font-size: 0.93rem;
}

/* RECENT PROJECTS */
.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 45px;
}

.projects-heading h2 {
  max-width: 600px;
}

.projects-heading p {
  max-width: 360px;
  margin: 0;
  color: var(--slate);
}

.projects-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 24px;
}

.project {
  min-width: 0;
  background: var(--white);
}

.project-image-wrap {
  overflow: hidden;
  aspect-ratio: 4 / 3;
  background: var(--sand);
}

.project-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 350ms ease;
}

.project:hover .project-image {
  transform: scale(1.035);
}

.project-copy {
  padding: 23px 24px 27px;
  border-bottom: 2px solid var(--orange);
}

.project-location {
  display: block;
  margin-bottom: 9px;
  color: var(--orange-dark);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.project-copy h3 {
  margin-bottom: 8px;
}

.project-copy p {
  margin: 0;
  color: var(--slate);
  font-size: 0.88rem;
}
