/* CSS PART 2 OF 2 */

/* CONTACT / CONVERSION */
.contact-section {
  padding: 110px 0;
  background: var(--ink-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 85px;
}

.contact-copy h2 {
  color: var(--white);
}

.contact-copy > p {
  max-width: 440px;
  margin-top: 22px;
  color: #c5ccce;
}

.contact-details {
  display: flex;
  flex-direction: column;
  gap: 17px;
  margin-top: 35px;
}

.contact-link {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  color: var(--white);
  font-size: 1rem;
  font-weight: 800;
}

.contact-link:hover {
  color: #e6a47e;
}

.contact-link-icon {
  display: grid;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  place-items: center;
  border: 1px solid rgba(255,255,255,.25);
  color: #e6a47e;
}

.contact-form {
  padding: 38px;
  background: var(--white);
  color: var(--ink);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 8px;
}

.form-intro {
  margin-bottom: 27px;
  color: var(--slate);
  font-size: 0.9rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 19px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 0.78rem;
  font-weight: 800;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid #d6d9d8;
  border-radius: 3px;
  background: #fbfbf9;
  color: var(--ink);
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #899397;
}

.form-submit {
  width: 100%;
  margin-top: 23px;
}

.form-note {
  margin: 13px 0 0;
  color: var(--muted);
  font-size: 0.75rem;
  text-align: center;
}

/* FOOTER */
.site-footer {
  padding: 38px 0;
  background: #111a1f;
  color: #c5ccce;
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.footer-brand {
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 800;
}

.footer-meta {
  margin: 5px 0 0;
  color: #9ba6aa;
  font-size: 0.76rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 25px;
}

.footer-links a {
  color: #c5ccce;
  font-size: 0.78rem;
  font-weight: 700;
}

.footer-links a:hover {
  color: #e6a47e;
}

/* TABLET */
@media (max-width: 1050px) {
  .container {
    width: min(100% - 48px, var(--container));
  }

  .header-inner {
    gap: 18px;
  }

  .main-nav {
    gap: 17px;
  }

  .main-nav a {
    font-size: 0.75rem;
  }

  .header-phone {
    display: none;
  }

  .hero-inner {
    grid-template-columns: 1fr 0.85fr;
  }

  .hero-copy {
    padding-right: 28px;
  }

  .approach-layout,
  .guide-layout {
    gap: 48px;
  }

  .roof-layout {
    gap: 42px;
  }

  .contact-layout {
    gap: 45px;
  }

  .projects-grid {
    gap: 16px;
  }

  .project-copy {
    padding: 20px;
  }
}

/* SMALL TABLET */
@media (max-width: 760px) {
  html {
    scroll-padding-top: 20px;
  }

  .container {
    width: calc(100% - 40px);
  }

  .section {
    padding: 76px 0;
  }

  .header-inner {
    min-height: 76px;
    flex-wrap: wrap;
    gap: 12px;
    padding: 12px 0;
  }

  .brand-mark {
    width: 40px;
    height: 40px;
  }

  .brand-name {
    font-size: 0.82rem;
  }

  .brand-description {
    font-size: 0.58rem;
  }

  .header-contact {
    margin-left: auto;
  }

  .header-contact .button {
    min-height: 44px;
    padding: 10px 14px;
    font-size: 0.72rem;
  }

  .main-nav {
    order: 3;
    width: 100%;
    justify-content: flex-start;
    gap: 23px;
    overflow-x: auto;
    padding: 7px 0 3px;
    scrollbar-width: thin;
  }

  .main-nav a {
    flex-shrink: 0;
    font-size: 0.78rem;
  }

  .hero-inner {
    grid-template-columns: 1fr;
  }

  .hero-copy {
    padding: 75px 0 50px;
  }

  .hero h1 {
    max-width: 600px;
    font-size: clamp(3rem, 11vw, 4.6rem);
  }

  .hero-visual {
    min-height: 390px;
  }

  .hero-proof {
    margin-top: 32px;
  }

  .approach-layout,
  .roof-layout,
  .guide-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 42px;
  }

  .approach-heading {
    position: static;
  }

  .approach-item {
    grid-template-columns: 42px 1fr;
  }

  .roof-image-wrap {
    min-height: 360px;
  }

  .roof-image {
    height: 360px;
  }

  .roof-image-label {
    right: 0;
  }

  .guide-heading {
    max-width: 600px;
  }

  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 17px;
    margin-bottom: 30px;
  }

  .projects-grid {
    grid-template-columns: 1fr 1fr;
    gap: 18px;
  }

  .project-copy {
    padding: 17px;
  }

  .project-copy h3 {
    font-size: 1.35rem;
  }

  .contact-section {
    padding: 78px 0;
  }

  .contact-form {
    padding: 27px;
  }

  .footer-inner {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* MOBILE */
@media (max-width: 480px) {
  .container {
    width: calc(100% - 36px);
  }

  .section {
    padding: 64px 0;
  }

  h2 {
    font-size: 2.35rem;
  }

  .header-inner {
    gap: 10px;
  }

  .brand {
    gap: 9px;
  }

  .brand-name {
    max-width: 165px;
    font-size: 0.76rem;
  }

  .brand-description {
    font-size: 0.53rem;
  }

  .header-contact .button {
    min-height: 42px;
    padding: 9px 11px;
    font-size: 0.67rem;
  }

  .main-nav {
    gap: 19px;
  }

  .hero-copy {
    padding: 62px 0 40px;
  }

  .hero h1 {
    font-size: clamp(2.8rem, 12vw, 3.8rem);
  }

  .hero-description {
    font-size: 0.98rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-proof {
    gap: 19px;
  }

  .hero-proof-item strong {
    font-size: 1.4rem;
  }

  .hero-proof-item span {
    font-size: 0.62rem;
  }

  .hero-visual {
    min-height: 310px;
  }

  .hero-caption {
    right: 12px;
    bottom: 12px;
    left: 12px;
    padding: 14px;
  }

  .roof-checklist {
    grid-template-columns: 1fr;
    gap: 13px;
  }

  .roof-image-wrap {
    min-height: 290px;
  }

  .roof-image {
    height: 290px;
  }

  .guide-step {
    grid-template-columns: 42px 1fr;
    gap: 12px;
  }

  .projects-grid {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .project-image-wrap {
    aspect-ratio: 4 / 3;
  }

  .contact-form {
    padding: 22px 18px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 15px;
  }

  .form-field--full {
    grid-column: auto;
  }

  .footer-links {
    gap: 16px;
  }
}

/* ACCESSIBILITY */
:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

.form-field input:focus-visible,
.form-field textarea:focus-visible,
.form-field select:focus-visible {
  border-color: var(--orange-dark);
  outline-color: var(--orange);
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
